use std::path::PathBuf;

use sha2::{Digest, Sha256};

pub fn hash_all(paths: &[PathBuf]) -> Vec<(PathBuf, String)> {
    paths
        .iter()
        .map(|path| {
            let bytes = std::fs::read(path).unwrap();
            let digest = Sha256::digest(&bytes);
            (path.clone(), format!("{digest:x}"))
        })
        .collect()
}

